"""Explain CAS retry observations, repeated guards and conditional decrement results."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1609': ('칠판의 5를 보고 2를 더할 준비를 했는데 다른 사람이 먼저 8로 바꾸었어요. 다시 시도할 때는 옛 5가 아니라 새로 확인한 8을 기준으로 계산해야 해요.', 'CAS 실패로 바뀐 관찰 값에서 조건과 후보를 다시 계산하는 이유를 이해합니다.', 'c=5·후보 7 → 다른 작업이 8로 변경 → 비교 실패·c=8 → 후보 10 재계산의 네 칸을 그리세요.', ['CAS는 예상한 값과 같을 때에만 새 값으로 바꾸는 비교 교체예요. 여기의 try_cmpxchg는 성공하면 true, 실패하면 false를 돌려줘요. 실패 때에는 예상 값이 있던 메모도 관찰한 현재 값으로 고쳐 줘요.', '조건부 산술 양식은 먼저 raw read로 읽은 값을 c에 담아요. c는 숫자판 자체가 아니라 “내가 마지막으로 본 숫자”를 적어 둔 메모예요. 읽은 뒤 다른 작업이 숫자판을 바꿀 수 있어요.', 'raw_try_cmpxchg(v, &c, 후보)를 부를 때 &c는 c 메모의 위치예요. 실패하면 함수가 이 위치에 새 관찰 값을 적어요. 그래서 다음 반복은 처음 read의 값이 아닌 갱신된 c로 시작해요.', '예를 들어 5에 2를 더하려던 순간 다른 작업이 8로 바꾸면 비교가 실패하고 c=8이 될 수 있어요. 다음 후보는 8+2=10이에요. 처음 만든 7을 계속 쓰면 새 관찰값에 2를 더한다는 뜻이 깨져요.', '조건도 매번 다시 봐야 해요. 새 c가 금지 값이거나 허용되지 않는 부호이면 더 이상 교체를 시도하지 않고 끝날 수 있어요. 반복은 무조건 성공할 때까지 같은 숫자를 쓰는 동작이 아니에요.', '정해진 횟수로 실패를 흉내 낸 모델은 그 사례에서 재계산이 맞는지 확인하는 연습이에요. 어떤 작업이 계속 기회를 못 얻는 기아가 모든 실행에서 없다는 증명은 아니에요. 재시도가 자료의 수명이나 모든 경우의 종료까지 자동 보장하지는 않아요.'], [('try_cmpxchg가 실패한 뒤 다음 반복에서 c는 무엇을 담고 있나요?', ['언제나 처음 read로 읽은 숫자 그대로예요', '실패한 비교가 관찰해 c 메모에 적어 준 값이에요'], '정답은 두 번째예요. &c를 넘겨 실패 때 그 메모를 고칠 수 있어요. 다음 조건과 후보 계산은 바뀐 c를 사용해야 해요.'), ('한 번 실패하도록 만든 연습 모델이 통과하면 모든 실행에서 기아가 없다는 증명인가요?', ['아니요. 지정한 실패·재시도 사례가 맞는지 확인한 것이에요', '네. 한 번 끝나면 모든 실행도 반드시 끝나요'], '정답은 첫 번째예요. 계산을 제대로 다시 했는지와 가능한 모든 경쟁 상황에서 완료하는지는 다른 질문이에요. 모델의 확인 범위를 넓혀 말하면 안 돼요.')]), 'os1610': ('“칠판이 0이면 더하지 마세요”라는 규칙은 처음 볼 때만 적용하는 것이 아니에요. 다시 보니 0이 되었다면 아까 허용됐더라도 멈춰야 해요.', '실패 후 금지 값을 다시 검사하고 이전 값으로 갱신 여부를 판단합니다.', '초기 5에서 실패로 c=0을 받는 경우는 저장 0·반환 0, c=2를 받는 경우는 다음 성공 시 저장 4·반환 2라고 적으세요. a=2, u=0이에요.', ['fetch_add_unless의 a는 더할 수, u는 “이 값이면 더하지 말기”라는 금지 값이에요. 먼저 c에 현재 값을 읽고 반복문 안에서 c == u인지 확인해요.', '같으면 break로 반복을 끝내요. 이 길에서는 덧셈 교체를 하지 않고 c를 반환해요. 다르면 c+a를 새 값 후보로 try_cmpxchg를 시도해요.', '처음 c=5, a=2, u=0이면 후보 7을 만들 수 있어요. 하지만 비교가 실패하며 c=0을 받으면 다음 반복에서 0 == 0을 확인하고 멈춰요. 처음 5가 허용됐다는 이유로 2를 더하면 안 돼요.', '실패로 c=2를 받았다면 2는 금지 값 0과 달라요. 다음 비교가 성공한다고 가정하면 2+2=4를 저장해요. 반환 c는 성공 직전 값 2예요. 처음 읽은 5도, 새 저장값 4도 아니에요.', 'add_unless 양식은 fetch_add_unless의 반환값이 u와 다른지를 비교해 bool을 만들어요. 반환 2와 u=0은 달라 true, 반환 0과 u=0은 같아 false예요. 성공 표시를 새 저장값이 1인지로 판단하지 않아요.', '이 예시는 작은 수의 계산이에요. 범위 초과나 자료가 언제 사라지는지는 별도 규칙이 필요해요. 금지 값 하나를 검사하는 기능이 모든 음수·끝값·수명 문제를 막는 보호 도구는 아니에요.'], [('처음 5를 읽었지만 CAS 실패가 금지 값 0을 관찰해 c에 적었어요. 다음 반복도 더하나요?', ['네. 처음 값 5가 허용돼서 무조건 더해요', '아니요. c와 금지 값을 다시 비교해 멈춰요'], '정답은 두 번째예요. 조건문이 반복 안에 있어서 새 c=0에도 적용돼요. 처음의 판단이 이후 상태까지 허락해 주지는 않아요.'), ('add_unless가 true·false를 만드는 기준은 무엇인가요?', ['fetch_add_unless의 반환값이 금지 값 u와 다른지예요', '새로 저장한 값이 무조건 1인지예요'], '정답은 첫 번째예요. 템플릿의 식은 fetch 결과 != u예요. 이전 값 반환을 이용해 조건부 갱신 여부를 구별하는 것이에요.')]), 'os1611': ('수직선의 허용 구역에 있던 숫자도 다른 작업 때문에 반대편으로 옮겨질 수 있어요. 재시도할 때마다 지금 관찰한 값이 허용 구역인지 다시 봐야 해요.', '부호 조건을 반복 안에서 다시 검사하고 0의 처리를 구별합니다.', 'inc_unless_negative는 c>=0, dec_unless_positive는 c<=0을 허용한다고 적으세요. 5→관찰 -1과 -5→관찰 1은 각각 중단 표시를 하세요.', ['inc_unless_negative는 음수가 아니면 1을 늘리는 함수예요. 양식은 반복 안에서 c<0이면 false를 반환하고, 아니면 c+1을 비교 교체로 시도해요. 0은 음수가 아니므로 허용돼요.', 'dec_unless_positive는 양수가 아니면 1을 줄이는 함수예요. c>0이면 false, 아니면 c-1을 시도해요. 0은 양수가 아니므로 후보 -1을 만들어요.', '증가 쪽에서 처음 5를 읽었다가 비교 실패로 c=-1이 되었다고 해 봅시다. 다음 반복은 -1<0을 확인하므로 false로 끝나요. -1을 0으로 증가시키는 다음 CAS는 하지 않아요.', '감소 쪽에서 처음 -5를 읽었다가 실패로 c=1을 받으면 다음 반복의 1>0이 참이에요. 따라서 감소시키지 않고 false로 끝나요. 처음 조건이 맞았다는 사실은 계속 유효한 허가증이 아니에요.', '비교 교체가 성공해 반복이 끝나면 true를 반환해요. 여기의 true는 결과가 양수라는 뜻이 아니라 허용된 갱신을 수행했다는 뜻이에요. 0에서 -1로 감소한 경우도 성공이면 true예요.', 'inc_not_zero의 조건은 0이 아닌지라서 부호 조건과 달라요. 비슷한 함수 이름을 보고 같은 범위라고 생각하지 마세요. 큰 정수 경계의 범위 초과는 별도 검토가 필요하며 이 연습은 작은 수로 조건을 확인해요.'], [('inc_unless_negative에서 실패 후 c가 -1로 바뀌면 다음 반복은 무엇을 하나요?', ['처음 양수였으므로 무조건 계속 증가시켜요', '음수 조건을 확인해 증가시키지 않고 false를 반환해요'], '정답은 두 번째예요. c<0 검사도 반복 안에 있어 새 관찰값에 적용돼요. 이전 값의 조건만 기억하면 금지된 상태에서 증가시키게 돼요.'), ('dec_unless_positive는 0에서 어떤 후보를 만들까요?', ['0-1인 -1을 만들어요', '0은 언제나 거부해서 후보가 없어요'], '정답은 첫 번째예요. 거부 조건은 c>0이고 0은 이에 해당하지 않아요. 후보를 만든 뒤 비교 교체 성공 여부는 별도로 확인해요.')]), 'os1612': ('사탕을 하나 꺼낼 계산을 했는데 그사이 통이 비었어요. 다시 확인한 개수로 계산하고, 꺼낼 수 없으면 통을 그대로 두어야 해요.', '마지막 감소 계산값과 실제 저장값을 구별합니다.', '처음 3에서 실패 관찰이 0이면 dec=-1·저장 0, 실패 관찰이 2이고 다음 시도가 성공하면 dec=1·저장 1로 적으세요.', ['dec_if_positive 양식은 처음 읽은 값을 c에 담고, 매 반복 dec=c-1을 계산해요. dec는 새 저장 후보인 동시에 마지막에 반환할 계산값이에요. c와 dec를 서로 다른 칸에 적어 보세요.', 'dec<0이면 break로 멈춰요. 이 갈래는 후보를 저장하지 않아요. 음수가 아니면 try_cmpxchg(v, &c, dec)로 대상이 아직 c일 때만 후보를 저장하려고 해요.', '처음 c=3이면 후보 dec=2예요. 비교에 실패하며 c=0을 받았다면 다음 반복에서 dec=0-1=-1로 다시 계산해요. 음수이므로 추가 감소 없이 끝내고 -1을 반환해요. 대상에는 0이 유지돼요.', '실패 때 c=2를 받았다면 다음 후보는 dec=1이에요. 그 다음 비교가 성공한다고 가정하면 1을 저장하고 1을 반환해요. 처음 만든 후보 2를 그대로 사용하지 않는 점이 중요해요.', '반환은 bool이 아니라 마지막 계산 dec예요. 시작 1에서 성공하면 저장 0·반환 0이므로 반환 0도 성공한 감소일 수 있어요. 반대로 0에서 멈출 때 반환 -1은 실제로 -1을 저장했다는 뜻이 아니에요.', '이 설명은 개수에 쓰는 0 이상의 작은 정상 입력 예시예요. 가장 작은 음수처럼 범위를 넘는 계산은 커널의 wrap 규칙과 실제 구현을 따로 확인해야 해요. 이 연산 하나가 참조 수 포화나 자료를 지워도 되는 권한까지 정해 주지는 않아요.'], [('처음 3에서 비교가 실패하고 0을 관찰했어요. 다음 반복의 반환과 저장은 무엇인가요?', ['처음 계산 2를 반환하고 -1을 저장해요', '다시 계산한 -1을 반환하고 저장값 0은 유지해요'], '정답은 두 번째예요. c=0으로 바뀌었으므로 dec=-1을 새로 계산해요. 음수라 저장하지 않고 종료해요. 반환값과 저장값을 따로 봐야 해요.'), ('dec_if_positive는 성공 여부를 true·false로 반환하나요?', ['아니요. 마지막으로 계산한 dec 숫자를 반환해요', '네. 성공할 때마다 true인 1을 반환해요'], '정답은 첫 번째예요. 본문의 끝은 return dec예요. 시작 1에서 성공하면 0을 반환할 수도 있으므로 bool 조건 함수들과 구별하세요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_398.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
